python3 - <<'PY'
import os, re

# All files with Store.GetUser calls (excluding driver GetUser)
files_and_patterns = [
    # We'll scan all go files for .GetUser( with FindUser
]

root = "/bench/repo"
results = []
for dirpath, _, filenames in os.walk(root):
    if "/proto/gen/" in dirpath or "node_modules" in dirpath:
        continue
    for fn in filenames:
        if not fn.endswith(".go"):
            continue
        path = os.path.join(dirpath, fn)
        with open(path) as f:
            lines = f.readlines()
        current_func = None
        for i, line in enumerate(lines, 1):
            m = re.match(r'^func\s+(\([^)]+\)\s+)?(\w+)', line)
            if m:
                recv = m.group(1) or ""
                name = m.group(2)
                current_func = (recv.strip(), name)
            if re.search(r'\.GetUser\(', line) and "FindUser" in line:
                # exclude driver? we'll include all then filter
                results.append((path.replace("/bench/repo/", ""), current_func, i, line.strip()))
            elif re.search(r'\.GetUser\(', line) and i+1 <= len(lines) and "FindUser" in lines[i]:
                results.append((path.replace("/bench/repo/", ""), current_func, i, line.strip()))

for path, fn, lineno, line in results:
    print(f"{fn} — {path}:{lineno}  |  {line}")
PY

